import{_ as e,o as r,c as t,a2 as i}from"./chunks/framework.C0KMm31j.js";const l="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_08_off_policy_split.png",n="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_08_q_target.png",o="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_08_sarsa_qlearning.png",h="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_08_max_bias.png",s="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_08_driving_boundary.png",g=JSON.parse('{"title":"行为在探索，目标却贪心：Q-learning 为什么能“边走边学最优”","description":"上一篇讲 Sarsa 时，我们看到一个看似细小却决定学习对象的选择：下一状态到来后，更新目标究竟使用实际选出的动作，还是使用当前价值最大的动作。Q-learning（Q 学习）选择后者。它可以继续用带探索的策略与环境交互，却让价值函数朝贪心策略的目标更新，因此成为最经典的 Off-Policy（异策","frontmatter":{"title":"行为在探索，目标却贪心：Q-learning 为什么能“边走边学最优”","description":"上一篇讲 Sarsa 时，我们看到一个看似细小却决定学习对象的选择：下一状态到来后，更新目标究竟使用实际选出的动作，还是使用当前价值最大的动作。Q-learning（Q 学习）选择后者。它可以继续用带探索的策略与环境交互，却让价值函数朝贪心策略的目标更新，因此成为最经典的 Off-Policy（异策","date":"2026-08-13","topic":"强化学习","section":"强化学习分类系列","readingTime":21,"source":"2026-08-13/rl_series_08_q_learning.md","status":"published","cover":"/article-assets/2026-08-13/rl_series_08_off_policy_split.png","head":[["link",{"rel":"canonical","href":"https://zpy560.github.io/Nav2ArticlesSite/rl/rl-series-08-q-learning"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"行为在探索，目标却贪心：Q-learning 为什么能“边走边学最优”"}],["meta",{"property":"og:description","content":"上一篇讲 Sarsa 时，我们看到一个看似细小却决定学习对象的选择：下一状态到来后，更新目标究竟使用实际选出的动作，还是使用当前价值最大的动作。Q-learning（Q 学习）选择后者。它可以继续用带探索的策略与环境交互，却让价值函数朝贪心策略的目标更新，因此成为最经典的 Off-Policy（异策"}],["meta",{"property":"og:url","content":"https://zpy560.github.io/Nav2ArticlesSite/rl/rl-series-08-q-learning"}],["meta",{"property":"og:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_08_off_policy_split.png"}],["meta",{"property":"article:published_time","content":"2026-08-13"}],["meta",{"name":"twitter:title","content":"行为在探索，目标却贪心：Q-learning 为什么能“边走边学最优”"}],["meta",{"name":"twitter:description","content":"上一篇讲 Sarsa 时，我们看到一个看似细小却决定学习对象的选择：下一状态到来后，更新目标究竟使用实际选出的动作，还是使用当前价值最大的动作。Q-learning（Q 学习）选择后者。它可以继续用带探索的策略与环境交互，却让价值函数朝贪心策略的目标更新，因此成为最经典的 Off-Policy（异策"}],["meta",{"name":"twitter:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_08_off_policy_split.png"}]],"prev":{"text":"为什么 Sarsa 会绕开悬崖？同策略学习真正“同”在哪里","link":"/rl/rl-series-07-sarsa"},"next":{"text":"奖励隔了十步才出现，前面的动作怎么分功？n 步 TD 与资格迹讲透了","link":"/rl/rl-series-09-n-step-td-eligibility-traces"}},"headers":[],"relativePath":"rl/rl-series-08-q-learning.md","filePath":"rl/rl-series-08-q-learning.md","lastUpdated":null}'),d={name:"rl/rl-series-08-q-learning.md"};function c(_,a,p,u,q,b){return r(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="行为在探索-目标却贪心-q-learning-为什么能-边走边学最优" tabindex="-1">行为在探索，目标却贪心：Q-learning 为什么能“边走边学最优” <a class="header-anchor" href="#行为在探索-目标却贪心-q-learning-为什么能-边走边学最优" aria-label="Permalink to &quot;行为在探索，目标却贪心：Q-learning 为什么能“边走边学最优”&quot;">​</a></h1><p>上一篇讲 Sarsa 时，我们看到一个看似细小却决定学习对象的选择：下一状态到来后，更新目标究竟使用实际选出的动作，还是使用当前价值最大的动作。Q-learning（Q 学习）选择后者。它可以继续用带探索的策略与环境交互，却让价值函数朝贪心策略的目标更新，因此成为最经典的 Off-Policy（异策略）时序差分控制方法。</p><p>Q-learning 的公式很短，但最容易被三个误解包围：异策略不等于任何历史数据都能无条件复用，最大动作价值不等于真实最优价值，表格环境中的收敛结论也不能直接搬到神经网络。真正理解它，需要同时拆开行为策略、目标策略、最大值算子和数据覆盖条件。</p><p>这篇文章沿着一条完整因果链展开：为什么 Sarsa 的实际下一动作可以被最大值替换，这个替换怎样分离“用谁采数据”和“想学谁”，为什么探索仍然不可少，最大化偏差从哪里出现，以及这些结论放到自动驾驶训练中时必须增加哪些安全边界。</p><h2 id="一、先给出整篇文章的结论" tabindex="-1">一、先给出整篇文章的结论 <a class="header-anchor" href="#一、先给出整篇文章的结论" aria-label="Permalink to &quot;一、先给出整篇文章的结论&quot;">​</a></h2><h3 id="_1-1-q-learning-学习贪心目标策略" tabindex="-1">1.1 Q-learning 学习贪心目标策略 <a class="header-anchor" href="#_1-1-q-learning-学习贪心目标策略" aria-label="Permalink to &quot;1.1 Q-learning 学习贪心目标策略&quot;">​</a></h3><p>Q-learning 的一步目标使用下一状态所有动作价值的最大值。这个最大值对应由当前 (Q) 派生的贪心 Target Policy（目标策略），而不是当前转移之后真正执行的下一动作。</p><h3 id="_1-2-数据可以由另一套策略产生" tabindex="-1">1.2 数据可以由另一套策略产生 <a class="header-anchor" href="#_1-2-数据可以由另一套策略产生" aria-label="Permalink to &quot;1.2 数据可以由另一套策略产生&quot;">​</a></h3><p>与环境交互的 Behavior Policy（行为策略）可以是 <code>ε</code>-贪心，甚至可以比目标策略更积极地探索。行为策略负责覆盖状态动作空间，目标策略定义价值函数希望逼近的决策规则，两者职责分离正是“异策略”的核心。</p><h3 id="_1-3-异策略并没有消灭探索" tabindex="-1">1.3 异策略并没有消灭探索 <a class="header-anchor" href="#_1-3-异策略并没有消灭探索" aria-label="Permalink to &quot;1.3 异策略并没有消灭探索&quot;">​</a></h3><p>若行为策略从不访问某个状态动作对，Q-learning 就得不到该位置的奖励和后继状态样本。目标中的 <code>max</code> 只会在已有估计里选最大值，不会凭空发现未尝试动作的真实后果。</p><h3 id="_1-4-最大值会放大估计噪声" tabindex="-1">1.4 最大值会放大估计噪声 <a class="header-anchor" href="#_1-4-最大值会放大估计噪声" aria-label="Permalink to &quot;1.4 最大值会放大估计噪声&quot;">​</a></h3><p>当多个动作价值都带有误差时，最大值算子更容易选中被高估的动作。这个 Maximization Bias（最大化偏差）不是说每次更新都必然高估，而是选择与评价共用同一组噪声估计时，统计上可能产生系统性正偏差。</p><p><img src="'+l+'" alt="Q-learning 将采样行为与贪心学习目标拆成两条路径"></p><h2 id="二、从-sarsa-走到-q-learning-只替换一项" tabindex="-1">二、从 Sarsa 走到 Q-learning 只替换一项 <a class="header-anchor" href="#二、从-sarsa-走到-q-learning-只替换一项" aria-label="Permalink to &quot;二、从 Sarsa 走到 Q-learning 只替换一项&quot;">​</a></h2><h3 id="_2-1-sarsa-使用实际下一动作" tabindex="-1">2.1 Sarsa 使用实际下一动作 <a class="header-anchor" href="#_2-1-sarsa-使用实际下一动作" aria-label="Permalink to &quot;2.1 Sarsa 使用实际下一动作&quot;">​</a></h3><p>Sarsa 的目标为：</p><p>$$ Y_t^{Sarsa}=R_{t+1}+\\gamma Q(S_{t+1},A_{t+1}) $$</p><p>其中 (A_{t+1}) 由当前行为策略选出，并会在后续交互中真正执行。若策略保留探索，随机动作的影响也进入学习目标。</p><h3 id="_2-2-q-learning-查询所有候选动作" tabindex="-1">2.2 Q-learning 查询所有候选动作 <a class="header-anchor" href="#_2-2-q-learning-查询所有候选动作" aria-label="Permalink to &quot;2.2 Q-learning 查询所有候选动作&quot;">​</a></h3><p>Q-learning 不等待实际下一动作进入目标，而是在 (S_{t+1}) 上查询所有可选动作，取当前估计最大的一个：</p><p>$$ Y_t^{Q}=R_{t+1}+\\gamma\\max_a Q(S_{t+1},a) $$</p><p>它回答的问题是：“已经走到下一状态，如果此后按当前认知选择价值最大的动作，这一步证据说明当前动作值多少？”</p><h3 id="_2-3-局部替换改变了策略语义" tabindex="-1">2.3 局部替换改变了策略语义 <a class="header-anchor" href="#_2-3-局部替换改变了策略语义" aria-label="Permalink to &quot;2.3 局部替换改变了策略语义&quot;">​</a></h3><p>公式只把 (Q(S_{t+1},A_{t+1})) 换成 (\\max_a Q(S_{t+1},a))，但前者评估实际行为策略，后者评估贪心目标策略。算法分类由更新目标在学习谁决定，不能只看采样时是否使用 <code>ε</code>-贪心。</p><h2 id="三、把-q-learning-更新公式逐项拆开" tabindex="-1">三、把 Q-learning 更新公式逐项拆开 <a class="header-anchor" href="#三、把-q-learning-更新公式逐项拆开" aria-label="Permalink to &quot;三、把 Q-learning 更新公式逐项拆开&quot;">​</a></h2><h3 id="_3-1-完整更新公式" tabindex="-1">3.1 完整更新公式 <a class="header-anchor" href="#_3-1-完整更新公式" aria-label="Permalink to &quot;3.1 完整更新公式&quot;">​</a></h3><p>一步 Q-learning 更新为：</p><p>$$ Q(S_t,A_t)\\leftarrow Q(S_t,A_t)+\\alpha\\left[R_{t+1}+\\gamma\\max_aQ(S_{t+1},a)-Q(S_t,A_t)\\right] $$</p><p>只有当前访问到的状态动作对 (Q(S_t,A_t)) 被写回，其余表项保持不变。</p><h3 id="_3-2-时序差分目标" tabindex="-1">3.2 时序差分目标 <a class="header-anchor" href="#_3-2-时序差分目标" aria-label="Permalink to &quot;3.2 时序差分目标&quot;">​</a></h3><p>目标 (Y_t^Q) 包含真实观察到的即时奖励，以及根据当前 (Q) 自举得到的下一状态最大动作价值。它不是环境直接给出的标签，而是“真实一步样本加当前估计”构成的移动目标。</p><h3 id="_3-3-时序差分误差" tabindex="-1">3.3 时序差分误差 <a class="header-anchor" href="#_3-3-时序差分误差" aria-label="Permalink to &quot;3.3 时序差分误差&quot;">​</a></h3><p>Q-learning 的 Temporal-Difference Error（时序差分误差）为：</p><p>$$ \\delta_t^Q=R_{t+1}+\\gamma\\max_aQ(S_{t+1},a)-Q(S_t,A_t) $$</p><p>误差为正，表示新证据比原预测更乐观；误差为负，表示原价值可能过高。学习率 (alpha) 决定本次修正幅度。</p><h3 id="_3-4-一个数字例子" tabindex="-1">3.4 一个数字例子 <a class="header-anchor" href="#_3-4-一个数字例子" aria-label="Permalink to &quot;3.4 一个数字例子&quot;">​</a></h3><p>假设 (Q(S_t,A_t)=2.0)，奖励为 (-1)，下一状态三个动作价值分别为 (1.0)、(3.0)、(2.5)，取 (\\gamma=0.9)、(\\alpha=0.1)。目标为 (-1+0.9\\times3.0=1.7)，误差为 (-0.3)，更新后价值为 (2.0+0.1\\times(-0.3)=1.97)。实际下一动作是否选中价值为 (3.0) 的动作，不影响这次目标。</p><p><img src="'+n+'" alt="Q-learning 目标由真实奖励和下一状态最大动作价值组成"></p><h2 id="四、行为策略和目标策略各自负责什么" tabindex="-1">四、行为策略和目标策略各自负责什么 <a class="header-anchor" href="#四、行为策略和目标策略各自负责什么" aria-label="Permalink to &quot;四、行为策略和目标策略各自负责什么&quot;">​</a></h2><h3 id="_4-1-行为策略决定数据分布" tabindex="-1">4.1 行为策略决定数据分布 <a class="header-anchor" href="#_4-1-行为策略决定数据分布" aria-label="Permalink to &quot;4.1 行为策略决定数据分布&quot;">​</a></h3><p>行为策略 (\\mu) 决定智能体实际访问哪些状态、执行哪些动作、看到哪些奖励。训练数据不是对整个环境的均匀扫描，而是这套行为策略与环境共同产生的分布。</p><h3 id="_4-2-目标策略决定学习方向" tabindex="-1">4.2 目标策略决定学习方向 <a class="header-anchor" href="#_4-2-目标策略决定学习方向" aria-label="Permalink to &quot;4.2 目标策略决定学习方向&quot;">​</a></h3><p>目标策略 (\\pi) 通常取相对于当前 (Q) 的贪心策略：</p><p>$$ \\pi(s)\\in\\arg\\max_a Q(s,a) $$</p><p>Q-learning 使用该策略对应的一步最优性目标，希望动作价值逐渐靠近最优动作价值 (q_*(s,a))。</p><h3 id="_4-3-两套策略通过同一张价值表耦合" tabindex="-1">4.3 两套策略通过同一张价值表耦合 <a class="header-anchor" href="#_4-3-两套策略通过同一张价值表耦合" aria-label="Permalink to &quot;4.3 两套策略通过同一张价值表耦合&quot;">​</a></h3><p>目标策略由当前 (Q) 派生，行为策略也常由同一张 (Q) 表构造为 <code>ε</code>-贪心。每次价值更新都会改变后续的贪心动作和探索基准，因此“分离”不表示两条互不影响的训练流水线。</p><h2 id="五、为什么这叫异策略学习" tabindex="-1">五、为什么这叫异策略学习 <a class="header-anchor" href="#五、为什么这叫异策略学习" aria-label="Permalink to &quot;五、为什么这叫异策略学习&quot;">​</a></h2><h3 id="_5-1-异-发生在采样与评价之间" tabindex="-1">5.1 “异”发生在采样与评价之间 <a class="header-anchor" href="#_5-1-异-发生在采样与评价之间" aria-label="Permalink to &quot;5.1 “异”发生在采样与评价之间&quot;">​</a></h3><p>数据可由含探索的 (\\mu) 产生，更新目标却使用贪心 (\\pi) 的后继价值。生成样本的策略与被学习的策略不相同，所以称为异策略。</p><h3 id="_5-2-当前动作仍来自真实样本" tabindex="-1">5.2 当前动作仍来自真实样本 <a class="header-anchor" href="#_5-2-当前动作仍来自真实样本" aria-label="Permalink to &quot;5.2 当前动作仍来自真实样本&quot;">​</a></h3><p>更新的是实际执行过的 (Q(S_t,A_t))，奖励和下一状态也必须来自这次真实或记录的转移。异策略并不是把当前动作替换成想象中的贪心动作，而是只在自举目标里使用目标策略。</p><h3 id="_5-3-一步-q-learning-不需要记录实际下一动作" tabindex="-1">5.3 一步 Q-learning 不需要记录实际下一动作 <a class="header-anchor" href="#_5-3-一步-q-learning-不需要记录实际下一动作" aria-label="Permalink to &quot;5.3 一步 Q-learning 不需要记录实际下一动作&quot;">​</a></h3><p>完成更新只需要 ((S_t,A_t,R_{t+1},S_{t+1}))。系统随后可以选择 (A_{t+1}) 继续交互，但这项不进入当前一步目标。与 Sarsa 相比，数据结构少了目标计算对实际下一动作的依赖。</p><h3 id="_5-4-异策略能力是经验复用的入口" tabindex="-1">5.4 异策略能力是经验复用的入口 <a class="header-anchor" href="#_5-4-异策略能力是经验复用的入口" aria-label="Permalink to &quot;5.4 异策略能力是经验复用的入口&quot;">​</a></h3><p>只要数据覆盖目标所需的状态动作对，并满足相应算法假设，Q-learning 可以从不等于当前贪心策略的数据中学习。这为 Experience Replay（经验回放）、历史日志和不同探索策略采集的数据复用提供了思路，但不代表任意离线数据都能可靠支持目标策略。</p><h2 id="六、ε-贪心为什么仍然不可少" tabindex="-1">六、<code>ε</code>-贪心为什么仍然不可少 <a class="header-anchor" href="#六、ε-贪心为什么仍然不可少" aria-label="Permalink to &quot;六、`ε`-贪心为什么仍然不可少&quot;">​</a></h2><h3 id="_6-1-max-只利用已有估计" tabindex="-1">6.1 <code>max</code> 只利用已有估计 <a class="header-anchor" href="#_6-1-max-只利用已有估计" aria-label="Permalink to &quot;6.1 `max` 只利用已有估计&quot;">​</a></h3><p>若某动作从未尝试，它的初始值可能长期保持不变。最大值算子只能比较表里的数值，无法知道未观察动作会得到什么奖励或进入什么状态。</p><h3 id="_6-2-探索为价值更新提供覆盖" tabindex="-1">6.2 探索为价值更新提供覆盖 <a class="header-anchor" href="#_6-2-探索为价值更新提供覆盖" aria-label="Permalink to &quot;6.2 探索为价值更新提供覆盖&quot;">​</a></h3><p><code>ε</code>-贪心以较大概率选择当前最大动作，以较小概率尝试其他动作。探索产生的转移让更多状态动作对获得更新机会，从而减少“因为没试过，所以永远不知道”的盲区。</p><h3 id="_6-3-探索率衰减需要兼顾两个目标" tabindex="-1">6.3 探索率衰减需要兼顾两个目标 <a class="header-anchor" href="#_6-3-探索率衰减需要兼顾两个目标" aria-label="Permalink to &quot;6.3 探索率衰减需要兼顾两个目标&quot;">​</a></h3><p>衰减太快会冻结错误的早期排序，长期固定较大 <code>ε</code> 又会让在线训练表现持续承受随机动作损失。理论表述常强调 Greedy in the Limit with Infinite Exploration（无限探索且极限贪心）：相关动作对持续获得样本，同时策略最终趋向贪心。</p><h3 id="_6-4-并列最大动作不应固定偏向数组首项" tabindex="-1">6.4 并列最大动作不应固定偏向数组首项 <a class="header-anchor" href="#_6-4-并列最大动作不应固定偏向数组首项" aria-label="Permalink to &quot;6.4 并列最大动作不应固定偏向数组首项&quot;">​</a></h3><p>初始化阶段常有大量相同价值。如果 <code>argmax</code> 永远返回首个索引，程序会制造与任务无关的动作偏好。更稳妥的实验实现是在并列最大动作中随机选择，并记录随机种子。</p><h2 id="七、一次完整交互循环怎样运行" tabindex="-1">七、一次完整交互循环怎样运行 <a class="header-anchor" href="#七、一次完整交互循环怎样运行" aria-label="Permalink to &quot;七、一次完整交互循环怎样运行&quot;">​</a></h2><h3 id="_7-1-初始化动作价值" tabindex="-1">7.1 初始化动作价值 <a class="header-anchor" href="#_7-1-初始化动作价值" aria-label="Permalink to &quot;7.1 初始化动作价值&quot;">​</a></h3><p>为非终止状态的可行动作设置初始 (Q)，再确定学习率、折扣因子、探索率和随机种子。乐观初始化可以促进早期探索，但也改变学习瞬态，必须作为实验条件报告。</p><h3 id="_7-2-用行为策略选择并执行动作" tabindex="-1">7.2 用行为策略选择并执行动作 <a class="header-anchor" href="#_7-2-用行为策略选择并执行动作" aria-label="Permalink to &quot;7.2 用行为策略选择并执行动作&quot;">​</a></h3><p>从 (S_t) 按 <code>ε</code>-贪心选择 (A_t)，执行后观察 (R_{t+1})、(S_{t+1}) 以及终止或截断标志。这里得到 Q-learning 所需的四元组。</p><h3 id="_7-3-用贪心目标完成更新" tabindex="-1">7.3 用贪心目标完成更新 <a class="header-anchor" href="#_7-3-用贪心目标完成更新" aria-label="Permalink to &quot;7.3 用贪心目标完成更新&quot;">​</a></h3><p>若转移未自然终止，就计算下一状态最大动作价值并更新当前表项；若自然终止，自举项取零。更新完成后再从下一状态采样行为动作，进入后续交互。</p><h3 id="_7-4-训练策略与评估策略分开" tabindex="-1">7.4 训练策略与评估策略分开 <a class="header-anchor" href="#_7-4-训练策略与评估策略分开" aria-label="Permalink to &quot;7.4 训练策略与评估策略分开&quot;">​</a></h3><p>训练时使用探索收集数据，评估时通常关闭探索并执行贪心策略。若把训练回报与贪心评估回报混在一起，就无法区分价值函数质量和探索噪声造成的损失。</p><h2 id="八、q-learning-与-sarsa-到底差在哪里" tabindex="-1">八、Q-learning 与 Sarsa 到底差在哪里 <a class="header-anchor" href="#八、q-learning-与-sarsa-到底差在哪里" aria-label="Permalink to &quot;八、Q-learning 与 Sarsa 到底差在哪里&quot;">​</a></h2><h3 id="_8-1-两者都能使用-ε-贪心采样" tabindex="-1">8.1 两者都能使用 <code>ε</code>-贪心采样 <a class="header-anchor" href="#_8-1-两者都能使用-ε-贪心采样" aria-label="Permalink to &quot;8.1 两者都能使用 `ε`-贪心采样&quot;">​</a></h3><p>只看动作选择日志，两种算法可能完全相同。它们都能在状态 (S_t) 用 <code>ε</code>-贪心执行 (A_t)，也都根据同一条环境转移更新当前动作价值。</p><h3 id="_8-2-sarsa-把实际下一动作放进目标" tabindex="-1">8.2 Sarsa 把实际下一动作放进目标 <a class="header-anchor" href="#_8-2-sarsa-把实际下一动作放进目标" aria-label="Permalink to &quot;8.2 Sarsa 把实际下一动作放进目标&quot;">​</a></h3><p>Sarsa 学习“按当前含探索策略继续行动”的价值。下一动作若来自随机探索，它的价值会直接影响前一步更新。</p><h3 id="_8-3-q-learning-把贪心下一动作放进目标" tabindex="-1">8.3 Q-learning 把贪心下一动作放进目标 <a class="header-anchor" href="#_8-3-q-learning-把贪心下一动作放进目标" aria-label="Permalink to &quot;8.3 Q-learning 把贪心下一动作放进目标&quot;">​</a></h3><p>Q-learning 学习“从下一状态开始按当前贪心策略行动”的价值。行为策略的随机动作负责生成样本，却不会作为 (A_{t+1}) 写进当前目标。</p><h3 id="_8-4-算法差异不能简化成保守与激进" tabindex="-1">8.4 算法差异不能简化成保守与激进 <a class="header-anchor" href="#_8-4-算法差异不能简化成保守与激进" aria-label="Permalink to &quot;8.4 算法差异不能简化成保守与激进&quot;">​</a></h3><p>在某些任务中，Sarsa 的在线路线看起来更谨慎，Q-learning 看起来更冒险，但这只是策略语义、探索和奖励结构共同作用的结果。换一个环境、探索调度或安全约束，现象可能改变。</p><p><img src="'+o+'" alt="Sarsa 与 Q-learning 使用同一转移，却构造不同的后继目标"></p><h2 id="九、悬崖行走揭示了什么" tabindex="-1">九、悬崖行走揭示了什么 <a class="header-anchor" href="#九、悬崖行走揭示了什么" aria-label="Permalink to &quot;九、悬崖行走揭示了什么&quot;">​</a></h2><h3 id="_9-1-最短路线紧贴高惩罚区域" tabindex="-1">9.1 最短路线紧贴高惩罚区域 <a class="header-anchor" href="#_9-1-最短路线紧贴高惩罚区域" aria-label="Permalink to &quot;9.1 最短路线紧贴高惩罚区域&quot;">​</a></h3><p>经典 Cliff Walking（悬崖行走）任务把起点和终点放在悬崖边缘。沿边路线步数少，但带探索策略的一次随机动作可能跌入悬崖，产生很大惩罚。</p><h3 id="_9-2-固定探索率下两种目标看到不同未来" tabindex="-1">9.2 固定探索率下两种目标看到不同未来 <a class="header-anchor" href="#_9-2-固定探索率下两种目标看到不同未来" aria-label="Permalink to &quot;9.2 固定探索率下两种目标看到不同未来&quot;">​</a></h3><p>Sarsa 的目标包含实际探索动作，因此会把未来继续探索的跌落风险计入路径价值。Q-learning 的目标使用贪心后继动作，学习的最优路线可以贴近悬崖，即使训练行为仍会因探索而偶尔跌落。</p><h3 id="_9-3-训练期回报与最终贪心路线可能相反" tabindex="-1">9.3 训练期回报与最终贪心路线可能相反 <a class="header-anchor" href="#_9-3-训练期回报与最终贪心路线可能相反" aria-label="Permalink to &quot;9.3 训练期回报与最终贪心路线可能相反&quot;">​</a></h3><p>固定 <code>ε</code> 时，Sarsa 可能取得更好的在线累计回报，而 Q-learning 学到更短的贪心路径。这里没有矛盾：一个指标包含训练时探索后果，另一个关注关闭探索后的目标策略。</p><h3 id="_9-4-教材现象不是安全证明" tabindex="-1">9.4 教材现象不是安全证明 <a class="header-anchor" href="#_9-4-教材现象不是安全证明" aria-label="Permalink to &quot;9.4 教材现象不是安全证明&quot;">​</a></h3><p>若探索率逐渐降为零，两种方法最终都可能靠近最短路径。真实车辆还存在连续动力学、感知误差、控制延迟和不可接受的碰撞代价，不能用悬崖行走路线替代道路安全论证。</p><h2 id="十、最大化偏差从哪里产生" tabindex="-1">十、最大化偏差从哪里产生 <a class="header-anchor" href="#十、最大化偏差从哪里产生" aria-label="Permalink to &quot;十、最大化偏差从哪里产生&quot;">​</a></h2><h3 id="_10-1-动作价值是带误差的估计" tabindex="-1">10.1 动作价值是带误差的估计 <a class="header-anchor" href="#_10-1-动作价值是带误差的估计" aria-label="Permalink to &quot;10.1 动作价值是带误差的估计&quot;">​</a></h3><p>有限样本下，每个 (Q(s,a)) 都可能高于或低于真实值。即使多个动作的真实价值相同，估计值也会因奖励噪声和访问次数不同而散开。</p><h3 id="_10-2-最大值更容易选中正误差" tabindex="-1">10.2 最大值更容易选中正误差 <a class="header-anchor" href="#_10-2-最大值更容易选中正误差" aria-label="Permalink to &quot;10.2 最大值更容易选中正误差&quot;">​</a></h3><p>假设某状态有多个真实价值都为零的动作，估计值在零附近波动。取平均时正负误差可能抵消，取最大值时却更可能挑中正误差最大的项，于是 (max_a Q(s,a)) 的期望可能高于真实最大值。</p><h3 id="_10-3-选择和评价共用一组估计" tabindex="-1">10.3 选择和评价共用一组估计 <a class="header-anchor" href="#_10-3-选择和评价共用一组估计" aria-label="Permalink to &quot;10.3 选择和评价共用一组估计&quot;">​</a></h3><p>标准 Q-learning 用同一张 (Q) 表决定哪个动作最大，又用该表的最大值评价这个动作。噪声既影响选择又影响数值，形成“挑中看起来最好者，再相信它看起来那么好”的统计耦合。</p><h3 id="_10-4-偏差会沿自举目标向前传播" tabindex="-1">10.4 偏差会沿自举目标向前传播 <a class="header-anchor" href="#_10-4-偏差会沿自举目标向前传播" aria-label="Permalink to &quot;10.4 偏差会沿自举目标向前传播&quot;">​</a></h3><p>被高估的下一状态价值进入当前目标，可能抬高前驱状态动作价值，再影响更早决策。偏差大小取决于噪声、动作数、数据量和函数表示，不能仅凭使用 <code>max</code> 就断言训练一定失败。</p><p><img src="'+h+'" alt="最大值更容易挑中带正误差的动作估计"></p><h2 id="十一、double-q-learning-怎样减弱偏差" tabindex="-1">十一、Double Q-learning 怎样减弱偏差 <a class="header-anchor" href="#十一、double-q-learning-怎样减弱偏差" aria-label="Permalink to &quot;十一、Double Q-learning 怎样减弱偏差&quot;">​</a></h2><h3 id="_11-1-核心思路是拆开选择与评价" tabindex="-1">11.1 核心思路是拆开选择与评价 <a class="header-anchor" href="#_11-1-核心思路是拆开选择与评价" aria-label="Permalink to &quot;11.1 核心思路是拆开选择与评价&quot;">​</a></h3><p>Double Q-learning（双 Q 学习）维护两套动作价值估计。一次更新可由 (Q_1) 选出下一状态的最大动作，再用 (Q_2) 评价该动作；另一次更新交换两者角色。</p><h3 id="_11-2-一种目标写法" tabindex="-1">11.2 一种目标写法 <a class="header-anchor" href="#_11-2-一种目标写法" aria-label="Permalink to &quot;11.2 一种目标写法&quot;">​</a></h3><p>更新 (Q_1) 时，非终止目标可以写成：</p><p>$$ Y_t^{Double}=R_{t+1}+\\gamma Q_2\\left(S_{t+1},\\arg\\max_a Q_1(S_{t+1},a)\\right) $$</p><p>决定动作的估计误差不再直接作为该动作的评价值，从而削弱选择噪声与评价噪声的同源耦合。</p><h3 id="_11-3-双估计不等于绝不低估" tabindex="-1">11.3 双估计不等于绝不低估 <a class="header-anchor" href="#_11-3-双估计不等于绝不低估" aria-label="Permalink to &quot;11.3 双估计不等于绝不低估&quot;">​</a></h3><p>拆分后可能减少正向最大化偏差，也可能在某些条件下出现低估。它解决的是特定统计机制，不是让价值估计自动准确，更不能替代数据覆盖和正确的终止处理。</p><h3 id="_11-4-它为深度方法中的双网络思想铺路" tabindex="-1">11.4 它为深度方法中的双网络思想铺路 <a class="header-anchor" href="#_11-4-它为深度方法中的双网络思想铺路" aria-label="Permalink to &quot;11.4 它为深度方法中的双网络思想铺路&quot;">​</a></h3><p>后续 Double DQN（双深度 Q 网络）同样强调动作选择与动作评价的分离，但表格型 Double Q-learning 与神经网络实现的训练机制并不完全相同。理解这里的统计动机，比只记住“两张表”更重要。</p><h2 id="十二、终止与截断为什么必须分开" tabindex="-1">十二、终止与截断为什么必须分开 <a class="header-anchor" href="#十二、终止与截断为什么必须分开" aria-label="Permalink to &quot;十二、终止与截断为什么必须分开&quot;">​</a></h2><h3 id="_12-1-自然终止没有后续回报" tabindex="-1">12.1 自然终止没有后续回报 <a class="header-anchor" href="#_12-1-自然终止没有后续回报" aria-label="Permalink to &quot;12.1 自然终止没有后续回报&quot;">​</a></h3><p>若到达任务定义的终止状态，后续回报为零，目标应写成 (Y_t=R_{t+1})。继续查询终止状态的最大动作价值，会给最后一步注入不存在的未来收益。</p><h3 id="_12-2-时间上限不一定代表任务结束" tabindex="-1">12.2 时间上限不一定代表任务结束 <a class="header-anchor" href="#_12-2-时间上限不一定代表任务结束" aria-label="Permalink to &quot;12.2 时间上限不一定代表任务结束&quot;">​</a></h3><p>若回合只是因训练器步数上限被截断，环境本身的动力学过程可能仍会继续。此时是否保留自举项取决于任务定义和接口语义，不能把 <code>terminated</code> 与 <code>truncated</code> 合并成一个布尔值后统一清零。</p><h3 id="_12-3-自动驾驶日志常存在人为切片" tabindex="-1">12.3 自动驾驶日志常存在人为切片 <a class="header-anchor" href="#_12-3-自动驾驶日志常存在人为切片" aria-label="Permalink to &quot;12.3 自动驾驶日志常存在人为切片&quot;">​</a></h3><p>固定时长片段、传感器中断或数据文件边界不一定是驾驶任务的自然终点。把每个切片末尾都当终止状态，会系统性压低靠近片段边界的价值估计。</p><h2 id="十三、表格型收敛结论有哪些前提" tabindex="-1">十三、表格型收敛结论有哪些前提 <a class="header-anchor" href="#十三、表格型收敛结论有哪些前提" aria-label="Permalink to &quot;十三、表格型收敛结论有哪些前提&quot;">​</a></h2><h3 id="_13-1-状态动作价值需要离散表示" tabindex="-1">13.1 状态动作价值需要离散表示 <a class="header-anchor" href="#_13-1-状态动作价值需要离散表示" aria-label="Permalink to &quot;13.1 状态动作价值需要离散表示&quot;">​</a></h3><p>经典证明针对表格型动作价值，每个状态动作对拥有可独立更新的表项。Watkins 与 Dayan 给出的结论不能不加说明地扩展到任意函数逼近器。</p><h3 id="_13-2-相关状态动作对要被反复访问" tabindex="-1">13.2 相关状态动作对要被反复访问 <a class="header-anchor" href="#_13-2-相关状态动作对要被反复访问" aria-label="Permalink to &quot;13.2 相关状态动作对要被反复访问&quot;">​</a></h3><p>若有动作长期不被采样，就无法保证它的估计得到纠正。探索策略、初始状态分布和环境可达性共同决定覆盖，并非仅设置一个非零 <code>ε</code> 就自然满足。</p><h3 id="_13-3-学习率需要满足随机逼近条件" tabindex="-1">13.3 学习率需要满足随机逼近条件 <a class="header-anchor" href="#_13-3-学习率需要满足随机逼近条件" aria-label="Permalink to &quot;13.3 学习率需要满足随机逼近条件&quot;">​</a></h3><p>理论上通常要求每个状态动作对对应的学习率随访问次数衰减，同时累计更新量不消失、平方和有限。实践中的常数学习率适合非平稳或有限训练，却不是原收敛定理的同一设置。</p><h3 id="_13-4-有限训练只能报告经验结果" tabindex="-1">13.4 有限训练只能报告经验结果 <a class="header-anchor" href="#_13-4-有限训练只能报告经验结果" aria-label="Permalink to &quot;13.4 有限训练只能报告经验结果&quot;">​</a></h3><p>真实实验只有有限回合和有限随机种子。应报告学习曲线、波动区间、状态动作覆盖和评估策略，而不是看到曲线暂时平稳就宣称已经数学收敛。</p><h2 id="十四、为什么神经网络会让问题更复杂" tabindex="-1">十四、为什么神经网络会让问题更复杂 <a class="header-anchor" href="#十四、为什么神经网络会让问题更复杂" aria-label="Permalink to &quot;十四、为什么神经网络会让问题更复杂&quot;">​</a></h2><h3 id="_14-1-函数逼近让多个状态共享参数" tabindex="-1">14.1 函数逼近让多个状态共享参数 <a class="header-anchor" href="#_14-1-函数逼近让多个状态共享参数" aria-label="Permalink to &quot;14.1 函数逼近让多个状态共享参数&quot;">​</a></h3><p>表格更新只改变一个表项，神经网络更新一个参数却可能同时改变许多状态动作的估计。新样本可能改善局部，也可能破坏其他区域原本合理的价值。</p><h3 id="_14-2-自举目标本身持续移动" tabindex="-1">14.2 自举目标本身持续移动 <a class="header-anchor" href="#_14-2-自举目标本身持续移动" aria-label="Permalink to &quot;14.2 自举目标本身持续移动&quot;">​</a></h3><p>网络既产生当前预测，又参与构造下一状态目标。参数变化会让监督目标随之变化，训练不再是固定数据集上的普通回归。</p><h3 id="_14-3-异策略数据带来分布差异" tabindex="-1">14.3 异策略数据带来分布差异 <a class="header-anchor" href="#_14-3-异策略数据带来分布差异" aria-label="Permalink to &quot;14.3 异策略数据带来分布差异&quot;">​</a></h3><p>经验可能由旧策略、探索策略或其他驾驶者产生，而当前网络正在优化另一套贪心目标。函数逼近、自举与异策略结合时常被称为 Deadly Triad（致命三角），可能造成不稳定甚至发散。</p><h3 id="_14-4-dqn-增加了稳定训练机制" tabindex="-1">14.4 DQN 增加了稳定训练机制 <a class="header-anchor" href="#_14-4-dqn-增加了稳定训练机制" aria-label="Permalink to &quot;14.4 DQN 增加了稳定训练机制&quot;">​</a></h3><p>Deep Q-Network（深度 Q 网络）使用经验回放打散相关样本，并用 Target Network（目标网络）在一段时间内固定自举目标。它继承 Q-learning 的最优性目标，但不能被理解成“把 Q 表直接换成神经网络”这么简单。</p><h2 id="十五、离线数据为什么不是越多越好" tabindex="-1">十五、离线数据为什么不是越多越好 <a class="header-anchor" href="#十五、离线数据为什么不是越多越好" aria-label="Permalink to &quot;十五、离线数据为什么不是越多越好&quot;">​</a></h2><h3 id="_15-1-数据只覆盖行为策略走过的区域" tabindex="-1">15.1 数据只覆盖行为策略走过的区域 <a class="header-anchor" href="#_15-1-数据只覆盖行为策略走过的区域" aria-label="Permalink to &quot;15.1 数据只覆盖行为策略走过的区域&quot;">​</a></h3><p>道路日志通常集中在正常驾驶状态，对临界失稳、罕见交互和危险动作覆盖不足。数据量巨大并不等于状态动作空间覆盖充分。</p><h3 id="_15-2-最大值可能选到分布外动作" tabindex="-1">15.2 最大值可能选到分布外动作 <a class="header-anchor" href="#_15-2-最大值可能选到分布外动作" aria-label="Permalink to &quot;15.2 最大值可能选到分布外动作&quot;">​</a></h3><p>目标在下一状态对所有动作取最大值，其中某个动作可能几乎没有出现在数据中。函数逼近器对该动作的高估若被 <code>max</code> 选中，就会生成缺少真实证据的乐观目标。</p><h3 id="_15-3-标准-q-learning-不是完整离线强化学习方案" tabindex="-1">15.3 标准 Q-learning 不是完整离线强化学习方案 <a class="header-anchor" href="#_15-3-标准-q-learning-不是完整离线强化学习方案" aria-label="Permalink to &quot;15.3 标准 Q-learning 不是完整离线强化学习方案&quot;">​</a></h3><p>在固定数据集上直接反复运行 Q-learning，无法主动探索并纠正分布外价值。可靠的 Offline Reinforcement Learning（离线强化学习）还要处理行为覆盖、保守价值估计和策略约束等问题。</p><h3 id="_15-4-数据来源必须可追踪" tabindex="-1">15.4 数据来源必须可追踪 <a class="header-anchor" href="#_15-4-数据来源必须可追踪" aria-label="Permalink to &quot;15.4 数据来源必须可追踪&quot;">​</a></h3><p>需要记录采集策略、场景分布、动作约束、终止定义和数据版本。若训练数据由多个控制器混合产生，却只报告“使用历史数据”，就无法判断异策略差异究竟有多大。</p><h2 id="十六、自动驾驶场景应怎样理解-q-learning" tabindex="-1">十六、自动驾驶场景应怎样理解 Q-learning <a class="header-anchor" href="#十六、自动驾驶场景应怎样理解-q-learning" aria-label="Permalink to &quot;十六、自动驾驶场景应怎样理解 Q-learning&quot;">​</a></h2><h3 id="_16-1-行为策略与部署策略可以分工" tabindex="-1">16.1 行为策略与部署策略可以分工 <a class="header-anchor" href="#_16-1-行为策略与部署策略可以分工" aria-label="Permalink to &quot;16.1 行为策略与部署策略可以分工&quot;">​</a></h3><p>仿真中的行为策略可加入受控探索以扩大覆盖，训练目标学习更接近贪心的策略，部署评估则关闭随机探索。这个分工是 Q-learning 对研究流程的重要启发。</p><h3 id="_16-2-真实道路不能直接执行无约束随机探索" tabindex="-1">16.2 真实道路不能直接执行无约束随机探索 <a class="header-anchor" href="#_16-2-真实道路不能直接执行无约束随机探索" aria-label="Permalink to &quot;16.2 真实道路不能直接执行无约束随机探索&quot;">​</a></h3><p>碰撞、越界和违反交通规则不是可接受的试错成本。探索应优先放在仿真、封闭场地或受安全过滤器约束的环境中，不能因为算法名为异策略就把高风险行为合理化。</p><h3 id="_16-3-奖励最大化不等于满足安全约束" tabindex="-1">16.3 奖励最大化不等于满足安全约束 <a class="header-anchor" href="#_16-3-奖励最大化不等于满足安全约束" aria-label="Permalink to &quot;16.3 奖励最大化不等于满足安全约束&quot;">​</a></h3><p>给碰撞设置大惩罚仍属于期望回报优化，不能自动给出每一步安全保证。安全约束、动作屏蔽、Control Barrier Function（控制屏障函数）或独立监控器应作为单独机制验证。</p><h3 id="_16-4-平均回报会掩盖尾部风险" tabindex="-1">16.4 平均回报会掩盖尾部风险 <a class="header-anchor" href="#_16-4-平均回报会掩盖尾部风险" aria-label="Permalink to &quot;16.4 平均回报会掩盖尾部风险&quot;">​</a></h3><p>两套策略平均回报相近时，碰撞率、最小安全距离、越界率和最坏场景回报仍可能差异显著。自动驾驶评估必须同时报告任务收益和风险指标。</p><p><img src="'+s+'" alt="自动驾驶 Q-learning 需要把训练探索、价值学习与部署安全分层"></p><h2 id="十七、一个最小实验应该怎样设计" tabindex="-1">十七、一个最小实验应该怎样设计 <a class="header-anchor" href="#十七、一个最小实验应该怎样设计" aria-label="Permalink to &quot;十七、一个最小实验应该怎样设计&quot;">​</a></h2><h3 id="_17-1-使用同一悬崖环境做单变量对照" tabindex="-1">17.1 使用同一悬崖环境做单变量对照 <a class="header-anchor" href="#_17-1-使用同一悬崖环境做单变量对照" aria-label="Permalink to &quot;17.1 使用同一悬崖环境做单变量对照&quot;">​</a></h3><p>保持状态、动作、奖励、起点分布、学习率、折扣因子和探索调度一致，只替换 Sarsa 与 Q-learning 的自举目标。这样才能把性能差异归因到学习对象，而不是实现细节。</p><h3 id="_17-2-同时记录训练和评估曲线" tabindex="-1">17.2 同时记录训练和评估曲线 <a class="header-anchor" href="#_17-2-同时记录训练和评估曲线" aria-label="Permalink to &quot;17.2 同时记录训练和评估曲线&quot;">​</a></h3><p>训练曲线保留探索，反映在线采样代价；评估曲线关闭探索，反映贪心策略质量。再记录跌落次数、路径长度和状态动作访问计数，避免只看平均回报。</p><h3 id="_17-3-使用多随机种子" tabindex="-1">17.3 使用多随机种子 <a class="header-anchor" href="#_17-3-使用多随机种子" aria-label="Permalink to &quot;17.3 使用多随机种子&quot;">​</a></h3><p>初始动作、探索轨迹和奖励噪声都会改变学习过程。应报告多个随机种子的均值与离散程度，并保留单次异常曲线用于定位问题。</p><h3 id="_17-4-增加最大化偏差小实验" tabindex="-1">17.4 增加最大化偏差小实验 <a class="header-anchor" href="#_17-4-增加最大化偏差小实验" aria-label="Permalink to &quot;17.4 增加最大化偏差小实验&quot;">​</a></h3><p>构造一个拥有多个等真实价值但奖励带噪声的后继状态，对比 Q-learning 与 Double Q-learning 的价值估计。重点观察被选动作价值和真实期望之间的差距，而不是只比较最终回报。</p><h2 id="十八、实现时最常见的错误" tabindex="-1">十八、实现时最常见的错误 <a class="header-anchor" href="#十八、实现时最常见的错误" aria-label="Permalink to &quot;十八、实现时最常见的错误&quot;">​</a></h2><h3 id="_18-1-把实际下一动作写进-q-learning-目标" tabindex="-1">18.1 把实际下一动作写进 Q-learning 目标 <a class="header-anchor" href="#_18-1-把实际下一动作写进-q-learning-目标" aria-label="Permalink to &quot;18.1 把实际下一动作写进 Q-learning 目标&quot;">​</a></h3><p>若代码先采样 (A_{t+1})，再用 (Q(S_{t+1},A_{t+1})) 更新，它实现的是 Sarsa 语义，而不是 Q-learning。变量名写着 <code>q_learning</code> 不能改变公式事实。</p><h3 id="_18-2-在自然终止状态继续取最大值" tabindex="-1">18.2 在自然终止状态继续取最大值 <a class="header-anchor" href="#_18-2-在自然终止状态继续取最大值" aria-label="Permalink to &quot;18.2 在自然终止状态继续取最大值&quot;">​</a></h3><p>终止状态没有可实现的未来动作价值。遗漏终止掩码会让最后奖励与虚构的后续价值相加，形成难以察觉的系统误差。</p><h3 id="_18-3-训练和评估共用探索率" tabindex="-1">18.3 训练和评估共用探索率 <a class="header-anchor" href="#_18-3-训练和评估共用探索率" aria-label="Permalink to &quot;18.3 训练和评估共用探索率&quot;">​</a></h3><p>评估时仍以非零 <code>ε</code> 随机行动，会把策略质量与探索噪声混合；只展示关闭探索后的最好成绩，又会掩盖训练采样过程中的风险。两类结果都应保留并明确标注。</p><h3 id="_18-4-用单条最好曲线代替统计结果" tabindex="-1">18.4 用单条最好曲线代替统计结果 <a class="header-anchor" href="#_18-4-用单条最好曲线代替统计结果" aria-label="Permalink to &quot;18.4 用单条最好曲线代替统计结果&quot;">​</a></h3><p>挑选表现最好的随机种子会高估方法稳定性。实验需要固定配置、保存全部种子结果，并说明均值、波动和失败次数。</p><h3 id="_18-5-把表格结论外推到连续控制" tabindex="-1">18.5 把表格结论外推到连续控制 <a class="header-anchor" href="#_18-5-把表格结论外推到连续控制" aria-label="Permalink to &quot;18.5 把表格结论外推到连续控制&quot;">​</a></h3><p>车辆转向和加速度通常是连续动作，朴素 Q-learning 需要离散化才能直接使用。动作网格过粗会限制控制精度，网格过细又扩大探索和估计成本，不能跳过这一建模取舍。</p><h2 id="十九、怎样真正掌握这一篇" tabindex="-1">十九、怎样真正掌握这一篇 <a class="header-anchor" href="#十九、怎样真正掌握这一篇" aria-label="Permalink to &quot;十九、怎样真正掌握这一篇&quot;">​</a></h2><h3 id="_19-1-能用一句话区分两套策略" tabindex="-1">19.1 能用一句话区分两套策略 <a class="header-anchor" href="#_19-1-能用一句话区分两套策略" aria-label="Permalink to &quot;19.1 能用一句话区分两套策略&quot;">​</a></h3><p>行为策略回答“数据由谁产生”，目标策略回答“价值函数想学谁”。Q-learning 允许这两个答案不同，但仍依赖行为数据覆盖目标学习所需区域。</p><h3 id="_19-2-能从四元组手算一次更新" tabindex="-1">19.2 能从四元组手算一次更新 <a class="header-anchor" href="#_19-2-能从四元组手算一次更新" aria-label="Permalink to &quot;19.2 能从四元组手算一次更新&quot;">​</a></h3><p>给定 (S_t)、(A_t)、(R_{t+1})、(S_{t+1})、动作价值表和超参数，应能独立计算最大后继价值、目标、误差和新表项，并正确处理自然终止。</p><h3 id="_19-3-能解释最大化偏差而不绝对化" tabindex="-1">19.3 能解释最大化偏差而不绝对化 <a class="header-anchor" href="#_19-3-能解释最大化偏差而不绝对化" aria-label="Permalink to &quot;19.3 能解释最大化偏差而不绝对化&quot;">​</a></h3><p>关键不是背诵“Q-learning 会高估”，而是说明同一组带噪估计同时负责选择和评价时，最大值在统计上可能偏高，以及双估计为何能减弱这种耦合。</p><h3 id="_19-4-能指出自动驾驶中的安全边界" tabindex="-1">19.4 能指出自动驾驶中的安全边界 <a class="header-anchor" href="#_19-4-能指出自动驾驶中的安全边界" aria-label="Permalink to &quot;19.4 能指出自动驾驶中的安全边界&quot;">​</a></h3><p>异策略数据复用不保证分布外可靠，奖励惩罚不等于硬安全约束，仿真探索也不能直接迁移到真实道路。只有把这些边界说清楚，Q-learning 才从一条公式变成可审计的方法。</p><p>下一篇将进入 n-step Temporal-Difference Learning（n 步时序差分学习）与 Eligibility Trace（资格迹）：一步更新传播得快还是慢，多步回报怎样在偏差和方差之间移动，以及 TD(λ) 为什么能把多种步长统一起来。</p><p><a href="https://github.com/datawhalechina/easy-rl/blob/master/docs/chapter3/chapter3.md" target="_blank" rel="noreferrer">《蘑菇书 EasyRL》第 3 章：Q-learning、异策略时序差分控制及与 Sarsa 的比较</a></p><p><a href="https://www.gatsby.ucl.ac.uk/~dayan/papers/wd92.html" target="_blank" rel="noreferrer">Watkins 与 Dayan 原始论文：Q-learning 更新与表格条件下的收敛结论</a></p><p><a href="https://web.stanford.edu/class/psych209/Readings/SuttonBartoIPRLBook2ndEd.pdf" target="_blank" rel="noreferrer">Sutton 与 Barto《Reinforcement Learning: An Introduction（强化学习导论）》第 6 章：Q-learning、悬崖行走和最大化偏差</a></p><p><a href="https://papers.neurips.cc/paper/3964-double-q-learning" target="_blank" rel="noreferrer">van Hasselt 论文：Double Q-learning（双 Q 学习）与最大化偏差</a></p><p><a href="https://www.youtube.com/watch?v=0g4j2k_Ggc4" target="_blank" rel="noreferrer">David Silver 强化学习课程第 5 讲：Model-Free Control（免模型控制）</a></p>',194)])])}const f=e(d,[["render",c]]);export{g as __pageData,f as default};
